//! What the index walks past, and how gently it walks. Caches, toolchains, build output and app
//! data are regenerated by their owners and never searched for by name; they were most of a home
//! folder's entries. Misty's own data (`~/.misty`, the Space drives with it) is never indexed, nor
//! are other apps' private data on macOS, which would ask the person for each app's permission.
use std::{
    collections::HashSet,
    ffi::OsString,
    path::{Path, PathBuf},
    time::{Duration, Instant},
};

/// The deepest a walk goes below the home folder.
pub(super) const MAX_DEPTH: usize = 18;

/// A walk runs in bursts of this long, then rests for half as long, so it uses at most about two
/// thirds of one core.
const BURST: Duration = Duration::from_millis(40);
const PAUSE: Duration = Duration::from_millis(20);

/// Folder names skipped wherever they appear: build output, dependency stores and caches.
const GENERATED_DIR_NAMES: &[&str] = &[
    ".git", "node_modules", "target", "dist", "build", ".next", ".cache", ".nuxt", ".svelte-kit",
    ".turbo", ".parcel-cache", ".gradle", ".venv", "__pycache__", ".mypy_cache", ".pytest_cache",
    ".tox", "DerivedData", "Pods", "bower_components", ".terraform",
];

/// Areas right under the home folder that hold application data rather than documents.
const GENERATED_HOME_DIRS: &[&str] = &[
    ".Trash", ".cache", ".npm", ".pnpm-store", ".yarn", ".bun", ".deno", ".cargo", ".rustup",
    ".gradle", ".m2", ".ivy2", ".nvm", ".pyenv", ".rbenv", ".gem", ".cocoapods", ".android",
    ".docker", ".vscode", ".cursor", ".local", ".colima", ".orbstack", ".misty", "AppData",
];

/// Inside ~/Library only these hold the person's documents (iCloud Drive and other cloud drives).
const LIBRARY_DOCUMENT_DIRS: &[&str] = &["Mobile Documents", "CloudStorage"];

/// Other apps' private data on macOS: walking it in the background would ask the person to
/// let Misty into each app's data.
fn protected_app_data(home: &Path) -> Vec<PathBuf> {
    if !cfg!(target_os = "macos") {
        return Vec::new();
    }
    let library = home.join("Library");
    [
        "Application Scripts",
        "Containers",
        "Daemon Containers",
        "Group Containers",
        "Calendars",
        "HomeKit",
        "Mail",
        "Messages",
        "PersonalizationPortrait",
        "Safari",
        "Suggestions",
    ]
    .iter()
    .map(|name| library.join(name))
    .chain([library.join("Application Support").join("AddressBook")])
    .collect()
}

/// What one walk of the home folder skips.
pub(super) struct ScanFilter {
    names: HashSet<OsString>,
    absolute: Vec<PathBuf>,
    home: PathBuf,
}

impl ScanFilter {
    pub(super) fn new(home: &Path) -> Self {
        let mut absolute = protected_app_data(home);
        // Misty's own data, wherever this build keeps it, never mind the home folder's name for it.
        if let Some(root) = file_access::paths::misty_root_dir() {
            absolute.push(root);
        }
        Self {
            names: GENERATED_DIR_NAMES.iter().map(OsString::from).collect(),
            absolute,
            home: home.to_path_buf(),
        }
    }

    pub(super) fn excludes(&self, path: &Path) -> bool {
        if path.file_name().is_some_and(|name| self.names.contains(name)) {
            return true;
        }
        if self.absolute.iter().any(|root| path.starts_with(root)) {
            return true;
        }
        if path.extension().is_some_and(|ext| {
            ext.eq_ignore_ascii_case("photoslibrary") || ext.eq_ignore_ascii_case("photolibrary")
        }) {
            return true;
        }
        generated_home_area(path, &self.home)
    }

    /// The depth of `path` below the home folder, if a walk would reach it: inside the home
    /// folder, no deeper than a walk goes, and nothing on the way excluded. The home folder itself
    /// is depth 0.
    pub(super) fn reach(&self, path: &Path) -> Option<usize> {
        let relative = path.strip_prefix(&self.home).ok()?;
        let mut current = self.home.clone();
        let mut depth = 0;
        for component in relative.components() {
            current.push(component);
            depth += 1;
            if depth > MAX_DEPTH || self.excludes(&current) {
                return None;
            }
        }
        Some(depth)
    }
}

fn generated_home_area(path: &Path, home: &Path) -> bool {
    let Ok(relative) = path.strip_prefix(home) else {
        return false;
    };
    let mut components = relative.components().map(|part| part.as_os_str());
    let Some(first) = components.next() else {
        return false;
    };
    if first == "Library" && cfg!(target_os = "macos") {
        let Some(second) = components.next() else {
            return false;
        };
        if !LIBRARY_DOCUMENT_DIRS.iter().any(|keep| second == *keep) {
            return true;
        }
        // A Space drive's own File Provider folder is Misty's, not the person's other files.
        return second == "CloudStorage"
            && components.next().is_some_and(|third| third.to_string_lossy().starts_with("Misty"));
    }
    GENERATED_HOME_DIRS.iter().any(|name| first == *name)
}

/// The walk's duty cycle.
pub(super) struct Pacer {
    burst_started: Instant,
    entries: u32,
}

impl Default for Pacer {
    fn default() -> Self {
        Self { burst_started: Instant::now(), entries: 0 }
    }
}

impl Pacer {
    pub(super) fn pace(&mut self) {
        self.entries = self.entries.wrapping_add(1);
        if !self.entries.is_multiple_of(256) || self.burst_started.elapsed() < BURST {
            return;
        }
        std::thread::sleep(PAUSE);
        self.burst_started = Instant::now();
    }
}

/// Runs the indexing thread at background priority (CPU and disk) while it lives.
pub(super) struct BackgroundPriority;

impl BackgroundPriority {
    pub(super) fn enter() -> Self {
        #[cfg(target_os = "macos")]
        // SAFETY: setpriority on the calling thread has no preconditions.
        unsafe {
            libc::setpriority(libc::PRIO_DARWIN_THREAD, 0, libc::PRIO_DARWIN_BG);
        }
        Self
    }
}

impl Drop for BackgroundPriority {
    fn drop(&mut self) {
        #[cfg(target_os = "macos")]
        // SAFETY: as above; 0 puts the thread back at its normal priority.
        unsafe {
            libc::setpriority(libc::PRIO_DARWIN_THREAD, 0, 0);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn caches_and_app_data_are_skipped_but_documents_are_not() {
        let home = PathBuf::from("/Users/example");
        let filter = ScanFilter::new(&home);
        assert!(filter.excludes(&home.join("code/app/node_modules")));
        assert!(filter.excludes(&home.join(".cargo")));
        assert!(filter.excludes(&home.join(".misty")));
        assert!(!filter.excludes(&home.join("Documents/notes.txt")));
        assert!(!filter.excludes(&home.join("Documents/.cargo")));
        assert_eq!(filter.reach(&home.join("Documents/a/b.txt")), Some(3));
        assert_eq!(filter.reach(&home.join("code/node_modules/x/y.js")), None);
        assert_eq!(filter.reach(Path::new("/Volumes/Other/file")), None);
        if cfg!(target_os = "macos") {
            assert!(filter.excludes(&home.join("Library/Caches/x")));
            assert!(!filter.excludes(&home.join("Library/Mobile Documents/com~apple~CloudDocs/a")));
            assert!(filter.excludes(&home.join("Library/CloudStorage/Misty-Family/a")));
            assert!(!filter.excludes(&home.join("Library/CloudStorage/Dropbox/a")));
            assert!(filter.excludes(&home.join("Library/Containers/com.example/Data")));
            assert!(filter.excludes(&home.join("Pictures/Family.photoslibrary")));
        }
    }
}
